-- Better Auth 1.7.7 schema delta over 0001_auth.sql for Shade's configuration:
-- emailAndPassword, rateLimit storage "database", no plugins, no social providers.
--
-- Derived with better-auth/db/migration getMigrations() against a database migrated through
-- 0005: user, session, account and verification already match 1.7.7, so the only missing
-- object is the rateLimit table (ids are text, generated by Better Auth; lastRequest is epoch ms).
-- Better Auth quotes camelCase identifiers, so they must stay double-quoted here.

create table if not exists "rateLimit" (
  "id" text not null primary key,
  "key" text not null unique,
  "count" integer not null,
  "lastRequest" bigint not null
);

-- One link per (provider, provider account id), so concurrent sign-ups or callbacks cannot
-- attach the same credential twice.
create unique index if not exists "account_providerId_accountId_uidx"
  on "account" ("providerId", "accountId");
